# Update stale tests and add focused contracts.
Path('test/admin-permissions-ui.test.js').write_text('''"use strict";\n\nvar assert = require("assert");\nvar fs = require("fs");\nvar path = require("path");\n\nvar root = path.resolve(__dirname, "..");\nvar view = fs.readFileSync(path.join(root, "views", "SIRK-Portal.handlebars"), "utf8");\nvar browser = fs.readFileSync(path.join(root, "web", "admin", "admin.js"), "utf8");\nvar runtime = fs.readFileSync(path.join(root, "server", "core", "runtime.js"), "utf8");\n\nassert.ok(view.indexOf('data-tab="permissions"') < 0, "Top-level Permissions tab must be removed.");\nassert.ok(browser.indexOf('tab === "permissions"') < 0, "Administration browser must not keep a second Permissions page owner.");\nassert.ok(browser.indexOf('modulePermissions(card, "My Commands", current.mycommands, folderData.mycommands, "Permissions")') >= 0, "My Commands must render its existing permission owner locally.");\nassert.ok(browser.indexOf('modulePermissions(card, "My Scripts", current.myscripts, scriptFolderData.myscripts, "Permissions")') >= 0, "My Scripts must render its existing permission owner locally.");\nassert.ok(browser.indexOf("Restrict module access to selected MeshCentral user groups") >= 0);\nassert.ok(browser.indexOf("Allow every user who has module access") >= 0);\nassert.ok(runtime.indexOf("moduleOptions.permissions") >= 0);\nassert.ok(runtime.indexOf("folderAccess.normalizeRules") >= 0);\nconsole.log("Admin module-local permissions UI contract: OK");\n''', encoding='utf-8')

Path('test/admin-move-request-policy-ui.test.js').write_text('''"use strict";\nvar assert = require("assert");\nvar fs = require("fs");\nvar path = require("path");\nvar root = path.resolve(__dirname, "..");\nvar browser = fs.readFileSync(path.join(root, "web", "admin", "admin.js"), "utf8");\nvar runtime = fs.readFileSync(path.join(root, "server", "core", "runtime.js"), "utf8");\nvar moduleSource = fs.readFileSync(path.join(root, "server", "modules", "move-requests", "index.js"), "utf8");\nassert.ok(browser.indexOf("Approval levels by target device group") >= 0);\nassert.ok(browser.indexOf("targetMeshApprovalLevels: moveApprovalLevels()") >= 0);\nassert.ok(browser.indexOf("var levels = explicit && Array.isArray(configured[meshId]) ? configured[meshId].map(Number) : [1]") >= 0, "Missing mesh policy must display effective Level 1 default.");\nassert.ok(runtime.indexOf("moveRequestAdmin:") >= 0, "Admin snapshot must include Move Request settings and meshes in one load.");\nassert.ok(runtime.indexOf("modules.moverequests.normalizeAdminSettings") >= 0, "Central save must reuse Move Requests normalization owner.");\nassert.ok(moduleSource.indexOf("function normalizeAdminSettings(value, user)") >= 0);\nassert.ok(moduleSource.indexOf("normalizeMeshApprovalLevels(value.targetMeshApprovalLevels, allowedMeshes)") >= 0);\nassert.ok(moduleSource.indexOf("getAdminSettings: getAdminSettings") >= 0);\nconsole.log("Admin Move Request per-target approval policy contract: OK");\n''', encoding='utf-8')

Path('test/admin-permissions-placement.test.js').write_text('''"use strict";\nvar assert = require("assert");\nvar fs = require("fs");\nvar path = require("path");\nvar root = path.resolve(__dirname, "..");\nvar browser = fs.readFileSync(path.join(root, "web", "admin", "admin.js"), "utf8");\nvar commandPayload = browser.slice(browser.indexOf('} else if (tab === "mycommands")'), browser.indexOf('} else {', browser.indexOf('} else if (tab === "mycommands")')));\nvar scriptPayload = browser.slice(browser.indexOf('} else {', browser.indexOf('} else if (tab === "mycommands")'), browser.indexOf('    function activate'));\nassert.ok(commandPayload.indexOf("permissions: { mycommands: commandPermissions() }") >= 0);\nassert.ok(commandPayload.indexOf("myscripts: scriptPermissions") < 0, "Commands save must not serialize Scripts permissions.");\nassert.ok(scriptPayload.indexOf("permissions: { myscripts: scriptPermissions() }") >= 0);\nassert.ok(scriptPayload.indexOf("mycommands: commandPermissions") < 0, "Scripts save must not serialize Commands permissions.");\nconsole.log("Admin permissions placement/partial-save browser contract: OK");\n''', encoding='utf-8')

